def candy_crush(board: list[list[int]]) -> list[list[int]]:
    rows, cols = len(board), len(board[0])
    while True:
        marked = [[False] * cols for _ in range(rows)]
        found = False
        # Mark horizontal triples.
        for r in range(rows):
            for c in range(cols - 2):
                v = board[r][c]
                if v and v == board[r][c + 1] == board[r][c + 2]:
                    marked[r][c] = marked[r][c + 1] = marked[r][c + 2] = True
                    found = True
        # Mark vertical triples.
        for r in range(rows - 2):
            for c in range(cols):
                v = board[r][c]
                if v and v == board[r + 1][c] == board[r + 2][c]:
                    marked[r][c] = marked[r + 1][c] = marked[r + 2][c] = True
                    found = True
        if not found:
            return board
        # Drop: compact surviving candies to the bottom of each column.
        for c in range(cols):
            write = rows - 1
            for r in range(rows - 1, -1, -1):
                if board[r][c] and not marked[r][c]:
                    board[write][c] = board[r][c]
                    write -= 1
            for r in range(write, -1, -1):
                board[r][c] = 0

class WordDictionary:
    def __init__(self):
        # Each node is a dict of children; the key "$" marks the end of a word.
        self.root = {}

    def addWord(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def search(self, word: str) -> bool:
        stack = [(self.root, 0)]
        while stack:
            node, i = stack.pop()
            if i == len(word):
                if "$" in node:
                    return True
                continue
            ch = word[i]
            if ch == ".":
                # A wildcard may follow any real child.
                for key, child in node.items():
                    if key != "$":
                        stack.append((child, i + 1))
            elif ch in node:
                stack.append((node[ch], i + 1))
        return False

