def majority_element(nums: list[int]) -> list[int]:
    cand_a, cand_b, count_a, count_b = None, None, 0, 0
    for x in nums:
        if x == cand_a:
            count_a += 1
        elif x == cand_b:
            count_b += 1
        elif count_a == 0:
            cand_a, count_a = x, 1
        elif count_b == 0:
            cand_b, count_b = x, 1
        else:
            count_a -= 1            # discard a triple of distinct values
            count_b -= 1
    # Verify the survivors with an exact count.
    limit = len(nums) // 3
    result = []
    for cand in (cand_a, cand_b):
        if cand is not None and cand not in result and nums.count(cand) > limit:
            result.append(cand)
    return result

