def num_squares(n: int) -> int:
    def is_square(x: int) -> bool:
        r = math.isqrt(x)
        return r * r == x

    if is_square(n):
        return 1
    # Legendre: n needs four squares exactly when n = 4^a * (8b + 7).
    m = n
    while m % 4 == 0:
        m //= 4
    if m % 8 == 7:
        return 4
    # Two squares: try each square a*a and test the remainder.
    for a in range(1, math.isqrt(n) + 1):
        if is_square(n - a * a):
            return 2
    return 3

