class _SkipNode:
    __slots__ = ("val", "next")

    def __init__(self, val: int, height: int):
        self.val = val
        self.next = [None] * height       # forward pointer per level


class Skiplist:
    MAX_LEVEL = 16

    def __init__(self):
        self.head = _SkipNode(-1, self.MAX_LEVEL)
        self.level = 1                    # number of levels currently in use

    def _descend(self, target: int) -> list:
        # update[i] = last node on level i whose value is < target
        update = [self.head] * self.MAX_LEVEL
        node = self.head
        for lv in range(self.level - 1, -1, -1):
            nxt = node.next[lv]
            while nxt is not None and nxt.val < target:
                node, nxt = nxt, nxt.next[lv]
            update[lv] = node
        return update

    def search(self, target: int) -> bool:
        node = self._descend(target)[0].next[0]
        return node is not None and node.val == target

    def add(self, num: int) -> None:
        update = self._descend(num)
        height = 1
        while height < self.MAX_LEVEL and random.random() < 0.5:
            height += 1
        self.level = max(self.level, height)
        node = _SkipNode(num, height)
        for lv in range(height):
            node.next[lv] = update[lv].next[lv]
            update[lv].next[lv] = node

    def erase(self, num: int) -> bool:
        update = self._descend(num)
        node = update[0].next[0]
        if node is None or node.val != num:
            return False
        for lv in range(len(node.next)):
            update[lv].next[lv] = node.next[lv]
        while self.level > 1 and self.head.next[self.level - 1] is None:
            self.level -= 1
        return True

