def sort_array(nums: list[int]) -> list[int]:
    # Counting sort: values are bounded, so count each one and replay in order.
    low, high = min(nums), max(nums)
    counts = [0] * (high - low + 1)
    for x in nums:
        counts[x - low] += 1

    result = []
    for offset, c in enumerate(counts):
        if c:
            result.extend([offset + low] * c)
    return result

