class MyQueue:
    def __init__(self):
        self.inbox = []    # receives pushes, newest on top
        self.outbox = []   # serves pops, oldest on top

    def push(self, x: int) -> None:
        self.inbox.append(x)

    def _refill(self) -> None:
        # Only move elements when outbox has run dry, keeping FIFO order.
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())

    def pop(self) -> int:
        self._refill()
        return self.outbox.pop()

    def peek(self) -> int:
        self._refill()
        return self.outbox[-1]

    def empty(self) -> bool:
        return not self.inbox and not self.outbox

