def rotate_the_box(box_grid: list[list[str]]) -> list[list[str]]:
    m, n = len(box_grid), len(box_grid[0])
    result = [["."] * m for _ in range(n)]
    for i, row in enumerate(box_grid):
        settled = row[:]
        drop = n - 1                     # where the next stone would land
        for j in range(n - 1, -1, -1):
            if settled[j] == "*":
                drop = j - 1
            elif settled[j] == "#":
                settled[j] = "."
                settled[drop] = "#"
                drop -= 1
        # Original row i becomes column m - 1 - i after a clockwise turn.
        col = m - 1 - i
        for j in range(n):
            result[j][col] = settled[j]
    return result

