def cherry_pickup(grid: list[list[int]]) -> int:
    n = len(grid)
    NEG = float("-inf")
    # dp[r1][r2]: best cherries with walkers at rows r1 <= r2 on diagonal t.
    dp = [[NEG] * n for _ in range(n)]
    dp[0][0] = grid[0][0]
    for t in range(1, 2 * n - 1):
        nxt = [[NEG] * n for _ in range(n)]
        lo, hi = max(0, t - n + 1), min(n - 1, t)
        for r1 in range(lo, hi + 1):
            c1 = t - r1
            if grid[r1][c1] == -1:
                continue
            for r2 in range(r1, hi + 1):
                c2 = t - r2
                if grid[r2][c2] == -1:
                    continue
                # Each walker arrived from above (row - 1) or from the left (same row).
                best = dp[r1][r2]
                if r1 > 0:
                    best = max(best, dp[r1 - 1][r2])
                    if r2 > 0:
                        best = max(best, dp[r1 - 1][r2 - 1])
                if r2 > r1:
                    best = max(best, dp[r1][r2 - 1])
                if best == NEG:
                    continue
                gain = grid[r1][c1] if r1 == r2 else grid[r1][c1] + grid[r2][c2]
                nxt[r1][r2] = best + gain
        dp = nxt
    return max(0, dp[n - 1][n - 1])

def find_celebrity(n: int) -> int:
    # Elimination pass: each knows() call rules out one person.
    candidate = 0
    for i in range(1, n):
        if knows(candidate, i):
            candidate = i

    # Verification pass: the survivor must truly be a celebrity.
    for i in range(n):
        if i == candidate:
            continue
        if knows(candidate, i) or not knows(i, candidate):
            return -1
    return candidate

