class Codec:
    def encode(self, strs: list[str]) -> str:
        # Each string becomes "<length>#<content>".
        return "".join(f"{len(s)}#{s}" for s in strs)

    def decode(self, s: str) -> list[str]:
        out = []
        i = 0
        while i < len(s):
            j = s.index("#", i)          # end of the length header
            length = int(s[i:j])
            out.append(s[j + 1:j + 1 + length])
            i = j + 1 + length           # jump past the content
        return out

