def minimum_time(n: int, relations: list[list[int]], time: list[int]) -> int:
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for prev, nxt in relations:
        graph[prev - 1].append(nxt - 1)
        indegree[nxt - 1] += 1

    start = [0] * n           # earliest month each course can begin
    queue = deque(i for i in range(n) if indegree[i] == 0)
    total = 0
    while queue:
        c = queue.popleft()
        finish = start[c] + time[c]
        total = max(total, finish)
        for d in graph[c]:
            if finish > start[d]:
                start[d] = finish
            indegree[d] -= 1
            if indegree[d] == 0:
                queue.append(d)
    return total

