def find_target_sum_ways(nums: list[int], target: int) -> int:
    total = sum(nums)
    if abs(target) > total:
        return 0
    offset = total                       # index = signed sum + offset
    ways = [0] * (2 * total + 1)
    ways[offset] = 1
    for x in nums:
        nxt = [0] * (2 * total + 1)
        for idx, count in enumerate(ways):
            if count:
                # Choose +x or -x for this number.
                if idx + x <= 2 * total:
                    nxt[idx + x] += count
                if idx - x >= 0:
                    nxt[idx - x] += count
        ways = nxt
    return ways[target + offset]

