class Excel:
    def __init__(self, height: int, width: str):
        self.values = {}      # (row, col) -> plain number
        self.formulas = {}    # (row, col) -> Counter of referenced cells

    def set(self, row: int, column: str, val: int) -> None:
        cell = (row, ord(column) - 65)
        self.formulas.pop(cell, None)          # a plain value replaces any formula
        self.values[cell] = val

    def get(self, row: int, column: str) -> int:
        return self._evaluate((row, ord(column) - 65))

    def sum(self, row: int, column: str, numbers: list[str]) -> int:
        refs = Counter()
        for ref in numbers:
            first, _, last = ref.partition(":")
            last = last or first
            r1, c1 = int(first[1:]), ord(first[0]) - 65
            r2, c2 = int(last[1:]), ord(last[0]) - 65
            for r in range(r1, r2 + 1):
                for c in range(c1, c2 + 1):
                    refs[(r, c)] += 1
        cell = (row, ord(column) - 65)
        self.formulas[cell] = refs
        return self._evaluate(cell)

    def _evaluate(self, target):
        # Iterative post order over the (acyclic) dependency graph.
        memo = {}
        stack = [(target, False)]
        while stack:
            cell, expanded = stack.pop()
            if cell in memo:
                continue
            refs = self.formulas.get(cell)
            if refs is None:
                memo[cell] = self.values.get(cell, 0)
            elif expanded:
                memo[cell] = sum(memo[ref] * times for ref, times in refs.items())
            else:
                stack.append((cell, True))
                for ref in refs:
                    if ref not in memo:
                        stack.append((ref, False))
        return memo[target]

