def get_permutation(n: int, k: int) -> str:
    digits = [str(d) for d in range(1, n + 1)]
    factorial = [1] * (n + 1)
    for i in range(1, n + 1):
        factorial[i] = factorial[i - 1] * i
    k -= 1                      # zero based rank
    out = []
    for remaining in range(n, 0, -1):
        block = factorial[remaining - 1]   # orderings per leading digit
        index, k = divmod(k, block)
        out.append(digits.pop(index))
    return "".join(out)

def last_stone_weight(stones: list[int]) -> int:
    heap = [-w for w in stones]   # negate to simulate a max heap
    heapq.heapify(heap)
    while len(heap) > 1:
        y = -heapq.heappop(heap)
        x = -heapq.heappop(heap)
        if y != x:
            heapq.heappush(heap, -(y - x))
    return -heap[0] if heap else 0

def min_malware_spread(graph: list[list[int]], initial: list[int]) -> int:
    n = len(graph)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x

    for i in range(n):
        row = graph[i]
        for j in range(i + 1, n):
            if row[j]:
                ri, rj = find(i), find(j)
                if ri != rj:
                    parent[ri] = rj
    size = collections.Counter(find(v) for v in range(n))
    infected = collections.Counter(find(v) for v in initial)

    best, best_saved = min(initial), 0
    for v in sorted(initial):
        root = find(v)
        # Only a lone infected machine's removal saves its component.
        if infected[root] == 1 and size[root] > best_saved:
            best, best_saved = v, size[root]
    return best

