def min_cut(s: str) -> int:
    n = len(s)
    # cuts[i] = fewest cuts for s[:i]; cut between every char as a start.
    cuts = [i - 1 for i in range(n + 1)]
    for center in range(n):
        # Odd length palindromes centered at `center`, then even length ones.
        for lo, hi in ((center, center), (center, center + 1)):
            while lo >= 0 and hi < n and s[lo] == s[hi]:
                if cuts[lo] + 1 < cuts[hi + 1]:
                    cuts[hi + 1] = cuts[lo] + 1
                lo -= 1
                hi += 1
    return cuts[n]

