def break_palindrome(palindrome: str) -> str:
    n = len(palindrome)
    if n == 1:
        return ""
    for i in range(n // 2):
        if palindrome[i] != "a":
            # Lowering this letter breaks the mirror and gives the smallest result.
            return palindrome[:i] + "a" + palindrome[i + 1:]
    # The first half is all 'a': raise the very last letter as little as possible.
    return palindrome[:-1] + "b"

