def num_islands2(m: int, n: int, positions: list[list[int]]) -> list[int]:
    parent = [-1] * (m * n)      # -1 means water

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x

    islands = 0
    answer = []
    for r, c in positions:
        cell = r * n + c
        if parent[cell] == -1:
            parent[cell] = cell
            islands += 1
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < m and 0 <= nc < n and parent[nr * n + nc] != -1:
                    a, b = find(cell), find(nr * n + nc)
                    if a != b:
                        parent[b] = a       # merge two islands into one
                        islands -= 1
        answer.append(islands)
    return answer

def find_duplicates(nums: list[int]) -> list[int]:
    dups = []
    for x in nums:
        v = abs(x)
        if nums[v - 1] < 0:
            dups.append(v)          # second time we meet v
        else:
            nums[v - 1] = -nums[v - 1]   # mark v as seen
    for i in range(len(nums)):   # restore the input
        nums[i] = abs(nums[i])
    return dups

