class FreqStack:
    def __init__(self):
        self.freq = collections.Counter()           # value -> current count
        self.levels = collections.defaultdict(list) # count -> stack of values
        self.max_level = 0

    def push(self, val: int) -> None:
        self.freq[val] += 1
        k = self.freq[val]
        self.levels[k].append(val)
        self.max_level = max(self.max_level, k)

    def pop(self) -> int:
        val = self.levels[self.max_level].pop()   # most frequent, newest on ties
        self.freq[val] -= 1
        if not self.levels[self.max_level]:
            self.max_level -= 1
        return val

